"""Colonist Ruins -- Hub 5 exterior zone

A restrained, grief-forward ruin zone about occupation, extraction, memory, and careful return rather than treasure-hunting spectacle."""

from world.area_builder import AreaBuilder


def build():
    area = AreaBuilder('colonist_ruins')

    area.zone(
        name='Colonist Ruins',
        zone_type='frontier',
        continent='veluana',
        tier=5,
        region='veluana_archipelago',
        hub_city='korahei',
        faction_territory='contested',
        faction_presence=['kauroran', 'raider', 'consortium'],
        world_x=72,
        world_y=-13,
        world_radius=135,
    )

    area.material('reef_silverjack', tier=1, terrain='water', absorbed_property='finesse', profession_bonus={'cooking': 0.1, 'fishing': 0.05})
    area.material('tide_eel', tier=2, terrain='water', absorbed_property='timing', profession_bonus={'cooking': 0.1, 'alchemy': 0.05})
    area.material('saltfruit', tier=1, terrain='coastal', absorbed_property='endurance', profession_bonus={'cooking': 0.1})
    area.material('hearthroot', tier=2, terrain='garden', absorbed_property='warmth', profession_bonus={'cooking': 0.1, 'alchemy': 0.05})
    area.material('tide_mint', tier=1, terrain='water', absorbed_property='cooling', profession_bonus={'alchemy': 0.1, 'cooking': 0.05})
    area.material('blackglass_shard', tier=2, terrain='ruins', absorbed_property='edge', profession_bonus={'smithing': 0.1, 'scholarship': 0.05})
    area.material('reefcrawler_shell', tier=1, terrain='reef', absorbed_property='protection', profession_bonus={'smithing': 0.1})
    area.material('saltpalm_wood', tier=1, terrain='coastal', absorbed_property='flexibility', profession_bonus={'engineering': 0.1})

    # Rooms
    ld_quiet_landing = area.room('ld_quiet_landing', name='Quiet Landing', desc='The southern boat grounds on a shore of broken pilings, salt-split beams, and careful warning cord. This is not a treasure beach; it is the first threshold into grief, hazard, and history.', room_type='ruins')
    ld_broken_dock = area.room('ld_broken_dock', name='Broken Dock', desc='The broken dock leans into the tide with iron staples still biting the old wood. New warning cords stand beside old extraction scars, making care and harm visible in the same glance.', room_type='ruins')
    ld_salt_split_beam = area.room('ld_salt_split_beam', name='Salt-Split Beam', desc='A saltpalm beam lies split where an imported pier once forced the shoreline straight. Fresh-cut notches mark the sound lengths Kau’roran crews may recover after the tide turns, while the rest remains braced against the wash.', room_type='ruins')
    ld_warning_cord_pile = area.room('ld_warning_cord_pile', name='Warning Cord Pile', desc='Coils of red and sea-green warning cord rest in a lidded basket above the spray. Knots retired from repaired hazards remain tied to their dated slats, leaving a plain record of which routes have changed since yesterday.', room_type='ruins')
    ld_imported_paving_crack = area.room('ld_imported_paving_crack', name='Imported Paving Crack', desc='Square paving stones stop abruptly at a fracture widened by saltfruit roots. Small shell markers distinguish ripe stems cleared for harvest from new growth being left to bind the disturbed soil.', room_type='ruins')
    ld_offering_above_surf = area.room('ld_offering_above_surf', name='Offering Above Surf', desc='A narrow shelf above the highest tide holds bread crusts, folded leaves, and bowls turned against the rain. Nothing identifies whom they honor; a clean arc of swept stone asks passing hands to leave that privacy intact.', room_type='ruins')
    ld_jackal_track_sand = area.room('ld_jackal_track_sand', name='Jackal Track Sand', desc='Jackal tracks cross the landing sand between warped planks and washed debris. The animals follow shelter and scraps, so clearing them protects visitors without pretending the ruins are only hostile.', room_type='ruins')
    ld_old_iron_staple = area.room('ld_old_iron_staple', name='Old Iron Staple', desc='An iron staple as broad as a hand pins nothing now, but rust stains trace the vanished dock timbers across the stone. A newer cord keeps feet clear without hiding the scale of what was built here to move cargo inland.', room_type='ruins')
    ld_low_wreck_shade = area.room('ld_low_wreck_shade', name='Low Wreck Shade', desc='The upturned ribs of a small workboat cast shade over a tide pocket where silverjack shelter. A woven tally hangs from the nearest rib, showing which catches the landing kitchen took and when the pool should be left alone.', room_type='ruins')
    ld_quiet_rope_post = area.room('ld_quiet_rope_post', name='Quiet Rope Post', desc='A quiet rope post marks where boats tie off before entering the ruin lanes. Jackals nose under the wreck shade nearby, drawn by offerings left too low and meals dropped by nervous hands.', room_type='ruins')
    ld_tide_bent_nail = area.room('ld_tide_bent_nail', name='Tide-Bent Nail', desc='A bent nail protrudes from a piling at shin height, wrapped in bright fiber after the last storm exposed it. Beside it, three wet knots on the guide cord warn that the lower stones disappear before the incoming tide looks dangerous.', room_type='ruins')
    ld_landing_rubble_shelf = area.room('ld_landing_rubble_shelf', name='Landing Rubble Shelf', desc='Storm-thrown masonry has been sorted into a low shelf: stable footing to one side, recorded occupation fragments to the other. Rain has blurred the oldest chalk marks, and a covered slate waits for the next patrol to renew them.', room_type='ruins')
    ld_broken_cargo_stone = area.room('ld_broken_cargo_stone', name='Broken Cargo Stone', desc='A cargo stone has cracked through its carved weight line, exposing a channel worn by years of rope. Shell counters set along the groove make the old measuring system readable without lifting the stone from the shore.', room_type='ruins')
    ld_mended_warning_board = area.room('ld_mended_warning_board', name='Mended Warning Board', desc='Saltpalm splints hold together a warning board whose oldest face was burned away. Its replaceable slats list today’s unstable wall, jackal shelter, and safe return tide in fresh charcoal rather than pretending the route stays fixed.', room_type='ruins')
    ld_south_debris_turn = area.room('ld_south_debris_turn', name='South Debris Turn', desc='The south turn bends around cargo stone, blackglass chips, and a windbreak made from old beams. Jackals use the clutter as cover, making the first combat loop a matter of clearing passage.', room_type='ruins')
    ld_blackglass_chip_sand = area.room('ld_blackglass_chip_sand', name='Blackglass Chip Sand', desc='Blackglass chips gleam among pale grains where a cargo jar shattered long ago. The sharpest pieces sit inside a marked sieve for the ruin keepers to catalogue; wave-rounded fragments remain in place, showing how far the spill has traveled.', room_type='ruins')
    ld_old_boat_scar = area.room('ld_old_boat_scar', name='Old Boat Scar', desc='Parallel grooves climb the beach where heavy boats were once dragged beyond the tide. Recent skiff marks cross them lightly, each paired with a shell token that lets the watch account for crews still inside the ruins.', room_type='ruins')
    ld_salt_warped_plank = area.room('ld_salt_warped_plank', name='Salt-Warped Plank', desc='A warped plank bridges a drainage cut only at low water, its repaired end stamped with the current patrol knot. Darkening salt lines beneath it preserve the heights of earlier surges and make the next safe crossing a matter of evidence.', room_type='ruins')
    ld_shore_ruin_mouth = area.room('ld_shore_ruin_mouth', name='Shore Ruin Mouth', desc='Burned stone closes around the shore path, muting surf and conversation alike. A braided threshold cord leaves one deliberate gap; beyond it, visitors enter on Kau’roran terms of witness, restraint, and return.', room_type='ruins')
    ld_last_landing_stone = area.room('ld_last_landing_stone', name='Last Landing Stone', desc='The final landing stone carries old wheel wear beneath fresher jackal tracks. Patrol marks point north toward the tended square and back toward the tide board, keeping both the reason for entering and the way home in view.', room_type='ruins')
    gr_grief_square = area.room('gr_grief_square', name='Grief Square', desc='The old square has been reclaimed for names, bowls, and low-voiced truth rather than victory display. Players arrive here to witness people before they treat the ruins as a problem to solve.', room_type='ruins')
    gr_pried_plaque_wall = area.room('gr_pried_plaque_wall', name='Pried Plaque Wall', desc='An old square has been reclaimed as a place for names, bowls, and low-voiced truth rather than conquest display. This part of the Grief Square centers on pried plaque wall, where names have been recarved beside older scars. The square gives emotional purpose to investigation: players are helping preserve people, not loot scenery.', room_type='ruins')
    gr_plain_bowl_row = area.room('gr_plain_bowl_row', name='Plain Bowl Row', desc="An old square has been reclaimed as a place for names, bowls, and low-voiced truth rather than conquest display. This part of the Grief Square centers on plain bowl row, where hearthroot grows in the square's warm cracks. The square gives emotional purpose to investigation: players are helping preserve people, not loot scenery.", room_type='ruins')
    gr_recarved_name_seat = area.room('gr_recarved_name_seat', name='Recarved Name Seat', desc='An old square has been reclaimed as a place for names, bowls, and low-voiced truth rather than conquest display. This part of the Grief Square centers on recarved name seat, where a bench faces inward so mourners do not perform grief. The square gives emotional purpose to investigation: players are helping preserve people, not loot scenery.', room_type='ruins')
    gr_warm_hearthroot_crack = area.room('gr_warm_hearthroot_crack', name='Warm Hearthroot Crack', desc='An old square has been reclaimed as a place for names, bowls, and low-voiced truth rather than conquest display. This part of the Grief Square centers on warm hearthroot crack, where the wind moves through empty window holes like breath. The square gives emotional purpose to investigation: players are helping preserve people, not loot scenery.', room_type='ruins')
