    ar_archive_shell = area.room('ar_archive_shell', name='Archive Shell', desc='The roofless archive holds brittle shelves, burnt ledgers, and fragments someone tried to erase. Clean shells weigh down paper scraps so the work stays about memory, not salvage value.', room_type='building')
    ar_charred_shelf_groove = area.room('ar_charred_shelf_groove', name='Charred Shelf Groove', desc='A roofless archive holds brittle shelves, burnt ledgers, and fragments that matter because someone tried to erase them. This part of the Archive Shell centers on charred shelf groove, where paper scraps have been weighted under clean shells. Records make the occupation legible without flattening anyone into simple villains or props.', room_type='building')
    ar_shell_weighted_scrap = area.room('ar_shell_weighted_scrap', name='Shell-Weighted Scrap', desc='A roofless archive holds brittle shelves, burnt ledgers, and fragments that matter because someone tried to erase them. This part of the Archive Shell centers on shell-weighted scrap, where blackglass shards catch light in dangerous slivers. Records make the occupation legible without flattening anyone into simple villains or props.', room_type='building')
    ar_blackglass_sliver_desk = area.room('ar_blackglass_sliver_desk', name='Blackglass Sliver Desk', desc='Blackglass slivers catch light across a desk where ledgers once sorted lives into cargo. Looters pry here because the fragments sell, while caretakers return because the names matter.', room_type='building')
